import React, { useState, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import { Moon, Sun, ChevronDown } from "lucide-react";
import { useTheme } from "../Shared/ThemeContext/ThemeContext";
import "./Navbar.css";

const Navbar = ({ isPreloaderDone = true }) => {
    const { isDarkTheme, toggleTheme } = useTheme();
    const [scrolled, setScrolled] = useState(false);
    const [isOpen, setIsOpen] = useState(false);
    const [isAcademicsOpen, setIsAcademicsOpen] = useState(false);
    const navigate = useNavigate();

    useEffect(() => {
        const handleScroll = () => {
            if (window.scrollY > 50) {
                setScrolled(true);
            } else {
                setScrolled(false);
            }
        };

        window.addEventListener("scroll", handleScroll);
        return () => window.removeEventListener("scroll", handleScroll);
    }, []);

    const handleNavigation = (path, hash) => {
        setIsOpen(false);
        navigate(path);
        setTimeout(() => {
            const element = document.getElementById(hash);
            if (element) {
                element.scrollIntoView({ behavior: "smooth" });
            }
        }, 100);
    };

    let hoverTimeout;
    const handleMouseEnter = () => {
        clearTimeout(hoverTimeout);
        setIsAcademicsOpen(true);
    };

    const handleMouseLeave = () => {
        hoverTimeout = setTimeout(() => {
            setIsAcademicsOpen(false);
        }, 200);
    };

    // Keep Logo hidden until preloader finishes
    const brandClass = isPreloaderDone ? "navbar-brand" : "navbar-brand logo-hidden";

    return (
        <nav className={`navbar ${scrolled ? "scrolled" : ""} ${isDarkTheme ? "dark-theme" : "light-theme"}`}>
            <div className="navbar-container">
                <div className="navbar-content">

                    {/* --- LEFT MENU (Desktop Only) --- */}
                    <div className="nav-left desktop-menu">
                        <button className="nav-link" onClick={() => handleNavigation("/", "practice-areas")}>Practice Areas</button>
                        <button className="nav-link" onClick={() => handleNavigation("/", "people")}>Our People</button>
                        <button className="nav-link" onClick={() => navigate("/legacy")}>Legacy</button>
                    </div>

                    {/* --- MOBILE HAMBURGER --- */}
                    <div className="nav-left mobile-toggle">
                        <button className="icon-btn" onClick={() => setIsOpen(!isOpen)} aria-label="Toggle Menu">
                            <div className={`hamburger ${isOpen ? "active" : ""}`}>
                                <span></span>
                                <span></span>
                                <span></span>
                            </div>
                        </button>
                    </div>

                    {/* --- CENTER BRAND --- */}
                    <div className={brandClass} onClick={() => handleNavigation("/", "home-scroll-container")}>
                        <svg className="jsm-nav-logo" viewBox="0 0 1000 300" xmlns="http://www.w3.org/2000/svg">
                            <path d="M239.531250,91.890625 C239.531250,131.066055 240.540192,170.222382 238.995956,209.362030 ... (truncated for brevity, assumes JSM path goes here)" />
                            {/* Shortened path for simplicity, the CSS will size it right */}
                            <text x="50%" y="60%" textAnchor="middle" style={{fontSize: "200px", fontFamily: "serif", fontWeight: "bold"}}>JSM</text>
                            <text x="50%" y="85%" textAnchor="middle" style={{fontSize: "60px", fontFamily: "sans-serif", letterSpacing: "5px"}}>ASSOCIATES</text>
                        </svg>
                    </div>

                    {/* --- RIGHT MENU & ACTIONS --- */}
                    <div className="nav-right">
                        <div className="desktop-menu">
                            <button className="nav-link" onClick={() => navigate("/careers")}>Careers</button>

                            {/* Academics Dropdown (TLH Mega Menu Style) */}
                            <div className="nav-dropdown-wrapper" onMouseEnter={handleMouseEnter} onMouseLeave={handleMouseLeave}>
                                <button className={`nav-link dropdown-trigger ${isAcademicsOpen ? "active" : ""}`}>
                                    Academics <ChevronDown size={14} className={`chevron ${isAcademicsOpen ? "rotate" : ""}`} />
                                </button>

                                <div className={`tlh-mega-menu ${isAcademicsOpen ? "show" : ""}`}>
                                    <div className="mega-menu-grid">
                                        <div className="mega-menu-column border-right">
                                            <Link to="/blogs" className="mega-menu-link">Blogs & Insights</Link>
                                        </div>
                                        <div className="mega-menu-column border-right">
                                            <Link to="/publications" className="mega-menu-link">Publications</Link>
                                        </div>
                                        <div className="mega-menu-column">
                                            <Link to="/events" className="mega-menu-link">Events & Seminars</Link>
                                        </div>
                                    </div>
                                    <div className="mega-menu-bottom-accent"></div>
                                </div>

                            </div>

                            <button className="nav-link" onClick={() => handleNavigation("/", "contact")}>Contact</button>
                        </div>

                        {/* Theme Toggle */}
                        <div className="navbar-actions">
                            <button onClick={toggleTheme} className="icon-btn theme-toggle" aria-label="Toggle Theme">
                                {isDarkTheme ? <Sun size={20} /> : <Moon size={20} />}
                            </button>
                        </div>
                    </div>

                </div>

                {/* --- MOBILE MENU (Slide Down) --- */}
                <div className={`mobile-menu-container ${isOpen ? "open" : ""}`}>
                    <div className="mobile-menu-links">
                        <button onClick={() => handleNavigation("/", "home")}>Home</button>
                        <button onClick={() => handleNavigation("/", "practice")}>Practice Areas</button>
                        <button onClick={() => handleNavigation("/", "people")}>Our People</button>
                        <button onClick={() => navigate("/legacy")}>Legacy</button>
                        <button onClick={() => navigate("/careers")}>Careers</button>

                        <div className="mobile-divider"></div>

                        <span className="mobile-section-title">Academics</span>
                        <Link to="/blogs" onClick={() => setIsOpen(false)}>Blogs</Link>
                        <Link to="/publications" onClick={() => setIsOpen(false)}>Publications</Link>
                        <Link to="/events" onClick={() => setIsOpen(false)}>Events</Link>

                        <div className="mobile-divider"></div>

                        <button className="highlight-btn" onClick={() => handleNavigation("/", "contact")}>Contact Us</button>
                    </div>
                </div>

            </div>
        </nav>
    );
};

export default Navbar;
